using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class FieldConvoyTests
{
    static readonly EntityId Home=new("site:castle"),Carrier=new("created:freight-carrier"),Job=new("request:camp-food");
    internal static WorldSession Start(){var seed=NpcFreightTests.Start().DiagnosticSnapshot().NewGame!;var s=new WorldSession(NewGameWorld.Create(seed.Start,seed.Registered,seed.Selected.Value,1,NewGameWorld.CompactPersonalAuthority,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:FieldConvoy.Policy));Send(s,NewMilitaryAction.Request);Advance(s,s.Seconds+2);OpenAll(s);Send(s,NewMilitaryAction.Accept);Advance(s,s.Seconds+2);OpenAll(s);Send(s,NewMilitaryAction.Pickup);return s;}
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long to){while(s.Seconds<to){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(to,100000);Assert.True(s.Seconds>old);}}
    static void OpenAll(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Good(s.Open(s.PlayerControl,m.Id,s.Revision));}
    static void Send(WorldSession s,NewMilitaryAction a,long n=0,FieldPoint? from=null,FieldPoint? to=null){var w=s.DiagnosticSnapshot();Good(s.DecideNewMilitary(new NewMilitaryInput(new("request:camp-military/"+s.Revision),a,n,from,to){AuthorityPolicy=a==NewMilitaryAction.Request?NewGameMilitary.AuthorityContract:null,LedgerPolicy=a==NewMilitaryAction.Request?NewGameMilitary.LedgerIdentityContract:null,FromLedger=a==NewMilitaryAction.Request?NewGameMilitary.SourceForCurrentHouse(w):null,CycleContract=a==NewMilitaryAction.Request?NewGameMilitary.CycleForCurrentHouse(w):null},s.PlayerControl,s.Revision));}
    static FieldPoint Camp(WorldSession s){var h=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);return new(h.X+30000,h.Y-10000);}
    static CommandResult Dispatch(WorldSession s,long kg=10,FieldPoint? point=null)=>s.ManageCampConvoy(new(Job,CampConvoyAction.Dispatch,Carrier:Carrier,Camp:point??Camp(s),RiceKg:kg),s.PlayerControl,s.Revision);
    static CampConvoyJob Current(WorldSession s)=>FieldConvoy.Jobs(s.DiagnosticSnapshot(),s.Seconds,s.Revision+1).Single();
    static void Load(WorldSession s){var v=s.MilitaryEconomyView()!;Good(s.ManageMilitaryRice(new(new("request:camp-load-source"),v.Depot,10),s.PlayerControl,s.Revision));Send(s,NewMilitaryAction.Load,10*MilitaryEconomy.PersonSecondsPerKg);}
    [Fact]public void DispatchDebitsRealHouseRiceButDoesNotTeleportOrRefillArmy(){var s=Start();long house=s.CommunityEconomyView()!.Accounts.HouseRice;Good(Dispatch(s));Assert.Equal(house-10,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Equal(0,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Assert.Equal(NewGameMilitary.Home(s.DiagnosticSnapshot(),0),FieldWorld.FromWorld(RegionalCampaign.ActorPointAt(s.DiagnosticSnapshot(),Carrier,s.Seconds)));Advance(s,s.Seconds+2);Assert.NotEqual(Home,s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Carrier).Site);Assert.Equal(0,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);}
    [Fact]public void CarrierWaitsAtAgreedCampWhenArmyIsAbsent(){var s=Start();Good(Dispatch(s));Advance(s,Current(s).Terms.Outbound[^1].EndAt+60);Assert.Equal(10,Current(s).CargoKg);Assert.Equal(0,Current(s).DeliveredKg);Assert.Equal(0,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Assert.Equal(Camp(s),FieldWorld.FromWorld(RegionalCampaign.ActorPointAt(s.DiagnosticSnapshot(),Carrier,s.Seconds)));}
    [Fact]public void MeetingArmyPhysicallyReceivesRiceAndContinuesActualConsumption(){var s=Start();Load(s);Good(Dispatch(s));var camp=Camp(s);Send(s,NewMilitaryAction.Deploy);Send(s,NewMilitaryAction.Form,from:camp,to:new(camp.X,camp.Y+10000));Advance(s,s.Seconds+100);Assert.Equal(10,Current(s).DeliveredKg);Assert.Equal(0,Current(s).CargoKg);Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).Carry>10*MilitaryEconomy.PersonSecondsPerKg);long before=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;Advance(s,s.Seconds+10);Assert.Equal(before-1000,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(w),ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(w))).DiagnosticSnapshot()));}
    [Fact]public void LocalCancellationReturnsActualUnusedRiceAfterWalkHome(){var s=Start();long before=s.CommunityEconomyView()!.Accounts.HouseRice;Good(Dispatch(s));Good(s.ManageCampConvoy(new(new("request:cancel-camp"),CampConvoyAction.CancelAtMeeting,Job),s.PlayerControl,s.Revision));Assert.Equal(before-10,s.CommunityEconomyView()!.Accounts.HouseRice);Advance(s,s.Seconds+2);Assert.NotNull(Current(s).Returned);Assert.Equal(before,s.CommunityEconomyView()!.Accounts.HouseRice);}

    [Theory][InlineData(0)][InlineData(-1)][InlineData(101)]public void InvalidQuantityDoesNotDebitHouse(long kg){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Dispatch(s,kg).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void CannotIssueToSelfOrBeyondExistingBattlefield(){var s=Start();var h=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Dispatch(s,point:new(h.X+121000,h.Y)).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageCampConvoy(new(Job,CampConvoyAction.Dispatch,Carrier:s.PlayerControl,Camp:Camp(s),RiceKg:10),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void AssignedCarrierCannotTakeAnotherJobOrBeRemoteRefilled(){var s=Start();Good(Dispatch(s));var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(new(new("request:double-carrier"),HouseFreightAction.Dispatch,Home:Home,Source:new("site:kofu"),Commodity:"wood",Quantity:1,Advance:1){Carrier=Carrier},s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageCampConvoy(new(new("request:forged-delivery"),CampConvoyAction.Deliver,Job),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void ExpiredWaitingConvoyWalksHomeAndReturnsUnusedRice(){var s=Start();long house=s.CommunityEconomyView()!.Accounts.HouseRice;Good(Dispatch(s));long deadline=Current(s).Terms.Until;Advance(s,deadline);Assert.NotNull(Current(s).ReturnStarted);Assert.Equal(10,Current(s).CargoKg);Assert.Equal(house-10,s.CommunityEconomyView()!.Accounts.HouseRice);Advance(s,Current(s).ReturnStarted!.ReturnRoute!.LastOrDefault()?.EndAt??s.Seconds+2);Assert.NotNull(Current(s).Returned);Assert.Equal(house,s.CommunityEconomyView()!.Accounts.HouseRice);}
    [Fact]public void FullMilitaryCapacityMakesConvoyWaitWithRealCargo(){var s=Start();var v=s.MilitaryEconomyView()!;Good(s.ManageMilitaryRice(new(new("request:full-army"),v.Depot,120),s.PlayerControl,s.Revision));Send(s,NewMilitaryAction.Load,NewGameMilitary.Capacity);Good(Dispatch(s));var camp=Camp(s);Send(s,NewMilitaryAction.Deploy);Send(s,NewMilitaryAction.Form,from:camp,to:new(camp.X,camp.Y+10000));Advance(s,s.Seconds+100);Assert.Equal(10,Current(s).CargoKg);Assert.Equal(0,Current(s).DeliveredKg);Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).Carry<NewGameMilitary.Capacity);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedSourceQuantityRouteOrOwnershipCannotLoad(int kind){var s=Start();Good(Dispatch(s));var w=s.DiagnosticSnapshot();var e=w.CampConvoys!.Entries.Single();w.CampConvoys=w.CampConvoys with{Entries=[e with{Terms=kind==0?e.Terms! with{RiceKg=999}:kind==1?e.Terms! with{Outbound=[]}:e.Terms! with{Owner=new("org:takeda")}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void ActualGenerationRecoveryPreservesGroundTravelDeliveryAndFuture(int phase)
    {
        var a=Start();Load(a);Good(Dispatch(a));if(phase>0)Advance(a,a.Seconds+2);if(phase>=2){Advance(a,Current(a).Terms.Outbound[^1].EndAt);if(phase>=3){var camp=Camp(a);Send(a,NewMilitaryAction.Deploy);Send(a,NewMilitaryAction.Form,from:camp,to:new(camp.X,camp.Y+10000));Advance(a,a.Seconds+60);if(phase==4)Advance(a,a.Seconds+60);}}
        a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"camp-convoy-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"camp",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("camp"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.CampConvoyView()),ContractJson.Write(b.CampConvoyView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"camp-convoy-"+phase+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,"camp-convoy-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}
        foreach(var q in new[]{a,b}){if(phase<3){var camp=Camp(q);Send(q,NewMilitaryAction.Deploy);Send(q,NewMilitaryAction.Form,from:camp,to:new(camp.X,camp.Y+10000));}Advance(q,q.Seconds+120);}Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(10,Current(a).DeliveredKg);
    }

    [Fact]public void NormalEntryBuildKeepsV15MilitaryAndPhysicalLetters(){var seed=NpcFreightTests.Start().DiagnosticSnapshot().NewGame!;var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"camp-normal-"+Guid.NewGuid().ToString("N")));var p=store.New(seed.Start,seed.Registered,seed.Selected.Value,1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,FieldConvoy.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));Assert.True(FreightOperations.Enabled(s.DiagnosticSnapshot()));Assert.NotNull(s.DiagnosticSnapshot().CampConvoys);Assert.NotNull(s.DiagnosticSnapshot().MilitaryEconomy);Assert.NotNull(s.HouseFreightView());}
    [Fact]public void V14AndEarlierCannotGainCampConvoysOrNewSaveFields(){var s=FreightOperationsTests.Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("CampConvoys",System.Text.Encoding.UTF8.GetString(b));Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.ManageCampConvoy(new(Job,CampConvoyAction.Dispatch,Carrier:Carrier,Camp:new(10000,10000),RiceKg:10),s.PlayerControl,s.Revision).Code);}
}
